<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { PaginationContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: PaginationContract  = $props();
const page=control(()=>p.page,untrack(()=>p.defaultPage),1,page=>p.onPageChange?.({page}));let draft=$state('');let invalid=$state(false);let previousShown=untrack(()=>p.loadMore?.shown);$effect(()=>{const shown=p.loadMore?.shown;if(shown!==undefined&&previousShown!==undefined&&shown>previousShown&&p.loadMore?.firstNewItemId){const id=p.loadMore.firstNewItemId;void tick().then(()=>document.getElementById(id)?.focus());}previousShown=shown;});const uid=$props.id();function activate(e:MouseEvent,next:number){if(e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();page.request(next);}function go(){const next=Number(draft);if(!/^\d+$/.test(draft)||next<1||next>p.pageCount){invalid=true;return;}invalid=false;page.request(next);}
</script>
<nav aria-label={p.variant==='load-more'?'결과 더보기':'페이지 이동'} {...owned('pagination','root',invalid&&'invalid')} >{#if p.variant==='load-more'&&p.loadMore}<button type="button" {...owned('pagination','load-more',p.loadMore.pending&&'pending',(p.loadMore.pending||p.loadMore.shown>=p.loadMore.total)&&'disabled')} disabled={p.loadMore.pending||p.loadMore.shown>=p.loadMore.total} onclick={event=>{event.currentTarget.focus();p.loadMore?.onLoadMore();}}>더 보기</button><span {...owned('pagination','count',p.loadMore.pending&&'pending')}>{p.loadMore.shown} / {p.loadMore.total}</span>{:else}<a href={page.value>1?p.hrefForPage(page.value-1):undefined} aria-disabled={page.value===1} {...owned('pagination','previous',page.value===1&&'disabled')} onclick={e=>{if(page.value>1)activate(e,page.value-1);}}>이전</a><ol {...owned('pagination','list')}>{#each Array.from({length:p.pageCount},(_,i)=>i+1) as item}<li {...owned('pagination','item',page.value===item&&'current')}><a href={page.value===item?undefined:p.hrefForPage(item)} aria-current={page.value===item?'page':undefined} {...owned('pagination','link',page.value===item&&'current')} onclick={e=>activate(e,item)}>{item}</a></li>{/each}</ol><a href={page.value<p.pageCount?p.hrefForPage(page.value+1):undefined} aria-disabled={page.value===p.pageCount} {...owned('pagination','next',page.value===p.pageCount&&'disabled')} onclick={e=>{if(page.value<p.pageCount)activate(e,page.value+1);}}>다음</a>{#if p.variant==='direct-page'}<label for={uid}>이동할 페이지</label><input id={uid} type="text" inputmode="numeric" bind:value={draft} aria-invalid={invalid||undefined} {...owned('pagination','input',invalid&&'invalid')} onkeydown={e=>{if(!ignoredKey(e)&&e.key==='Enter'){e.preventDefault();go();}}}/><button type="button" {...owned('pagination','go')} onclick={go}>이동</button>{/if}{/if}</nav>
